import { LogicWrapper, MakeLogicType, actions, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { signalsReportChecksProgressRetrieve } from 'products/signals/frontend/generated/api'
import type { SignalReportCheckProgressApi } from 'products/signals/frontend/generated/api.schemas'

export interface ReportCheckProgressLogicProps {
    reportId: string
    periodKey: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCheckProgressLogicValues {
    progress: SignalReportCheckProgressApi[] | null
    progressError: boolean
    progressLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCheckProgressLogicActions {
    loadProgress: (_: void) => void
    loadProgressFailure: (
        error: string,
        errorObject?: unknown
    ) => {
        error: string
        errorObject: unknown
    }
    loadProgressSuccess: (
        progress: SignalReportCheckProgressApi[],
        payload?: void
    ) => {
        progress: SignalReportCheckProgressApi[]
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportCheckProgressLogicMeta {
    key: string
}

export type reportCheckProgressLogicType = MakeLogicType<
    reportCheckProgressLogicValues,
    reportCheckProgressLogicActions,
    ReportCheckProgressLogicProps,
    reportCheckProgressLogicMeta
>

export const reportCheckProgressLogic: LogicWrapper<reportCheckProgressLogicType> = kea<reportCheckProgressLogicType>([
    props({} as ReportCheckProgressLogicProps),
    key(({ reportId, periodKey }) => `${reportId}.${periodKey}`),
    path((key) => ['products', 'signals', 'inbox', 'reportCheckProgressLogic', key]),
    actions({
        loadProgressFailure: (error: string, errorObject?: unknown): { error: string; errorObject: unknown } => ({
            error,
            errorObject,
        }),
    }),
    loaders(({ props }) => ({
        progress: [
            null as SignalReportCheckProgressApi[] | null,
            {
                loadProgress: async (_: void, breakpoint): Promise<SignalReportCheckProgressApi[]> => {
                    if (!props.periodKey) {
                        return []
                    }
                    const periodKey = props.periodKey
                    const response = await signalsReportChecksProgressRetrieve(
                        String(teamLogic.values.currentTeamId),
                        props.reportId
                    )
                    await breakpoint()
                    return props.periodKey === periodKey ? response : []
                },
            },
        ],
    })),
    reducers({
        progressError: [
            false,
            {
                loadProgress: () => false,
                loadProgressSuccess: () => false,
                loadProgressFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions, props }) => {
        if (props.periodKey) {
            actions.loadProgress()
        }
    }),
])
